import { useState, useEffect, useMemo, useRef } from "react";

import { StudioProApi } from "@mendix/extensions-api";

import { EntityIcon } from "@mendix/ide-icons/EntityIcon";
import { EntityNonPersistableIcon } from "@mendix/ide-icons/EntityNonPersistableIcon";
import { TextArea } from "@mendix/ide-ui-components/input/TextArea";

import { componentName } from "../../main/index";

import { Agent } from "../../types/agent";
import { ToolValidationState } from "../../types/tool";
import { createHighlightRules, getMissingAttributes, getUnusedAttributes } from "../../utils/agentUtils";
import {
    handleValidateAgent,
    handleAgentChangeValue,
    handleSelectEntity,
    handleSelectModel,
    handleShowModel,
    handleEditModelSettings,
} from "./agentHandlers";
import { getEntity, handleShowEntity, isPersistableEntity } from "../../utils/domainModelUtils";

import { InfoBanner, WarningBanner } from "../components/Banner";
import GroupBox from "../components/GroupBox";
import { ContentColumn } from "../components/PageContainers";
import TextAreaLabeled from "../components/TextAreaLabeled";
import TextInputWithButton from "../components/TextInputWithButton";
import { mendixCloudGenAIIconBase64 } from "../../icons/modelIcons";
import ToolsTable from "./toolsTable";
import { handleValidateTool } from "../tool/toolHandlers";
import { useTheme } from "styled-components";

interface AgentProps {
    loadedAgent: Agent;
    studioPro: StudioProApi;
    updateStudioProDocument: (agent: Agent) => Promise<void>;
}

type ValidationInfo = {
    isValidModel: true | string;
    isValidEntity: true | string;
    isValidUserPrompt: true | string;
    showCreateVariablesInfo: boolean;
    missingAttributes: string[];
    unusedAttributes: string[];
};

const initialValidationInfo: ValidationInfo = {
    isValidModel: true,
    isValidEntity: true,
    isValidUserPrompt: true,
    showCreateVariablesInfo: false,
    missingAttributes: [],
    unusedAttributes: [],
};

const AgentEditor: React.FC<AgentProps> = ({ loadedAgent, studioPro, updateStudioProDocument }) => {
    const [isLoaded, setIsLoaded] = useState(false);
    const [validationInfo, setValidationInfo] = useState(initialValidationInfo);
    const [entityIcon, setEntityIcon] = useState<React.ReactElement | undefined>(undefined);
    const [agent, setAgent] = useState(loadedAgent);
    const [hideUnusedAttributes, setHideUnusedAttributes] = useState(false);
    const [hideNoVariables, setHideNoVariables] = useState(false);
    const [toolValidations, setToolValidations] = useState<Map<string, ToolValidationState>>(new Map());
    const theme = useTheme();

    // Ref for debouncing document updates
    const debounceTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        validateAgent(loadedAgent).then((v) => setValidationInfo(v));
        getEntityIcon(studioPro, loadedAgent.entity).then((e) => setEntityIcon(e));
        setAgent(loadedAgent);
        setIsLoaded(true);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Cleanup debounce timeout on unmount
    useEffect(() => {
        return () => {
            if (debounceTimeout.current) {
                clearTimeout(debounceTimeout.current);
            }
        };
    }, []);

    useEffect(() => {
        const updateEntityIcon = async () => {
            const icon = await getEntityIcon(studioPro, agent.entity);
            setEntityIcon(icon);
        };

        if (isLoaded) {
            updateEntityIcon();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [studioPro, agent.entity]);

    useEffect(() => {
        const validateTools = async () => {
            if (agent.tools && agent.tools.length > 0) {
                // Set all tools to syncing state
                const syncingStates = new Map<string, ToolValidationState>();
                agent.tools.forEach((tool) => {
                    if (tool.microflow) {
                        syncingStates.set(tool.id, "syncing");
                    }
                });
                setToolValidations(syncingStates);

                // Validate each tool
                const validationResults = await Promise.all(
                    agent.tools.map(async (tool) => {
                        if (tool.microflow) {
                            const validationResult = await handleValidateTool("microflow", tool, studioPro, agent);
                            return {
                                id: tool.id,
                                state:
                                    validationResult === true
                                        ? ("valid" as ToolValidationState)
                                        : ("invalid" as ToolValidationState),
                            };
                        }
                        return { id: tool.id, state: "valid" as ToolValidationState };
                    })
                );

                // Update validation states
                const newValidations = new Map(validationResults.map((r) => [r.id, r.state]));
                setToolValidations(newValidations);
            }
        };

        if (isLoaded) {
            validateTools();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isLoaded]);

    // When tools change after initial load, handle new/edited tools
    // Store microflow values separately since tool objects can be mutated
    const prevMicroflowsRef = useRef<Map<string, string>>(new Map());

    useEffect(() => {
        if (isLoaded && agent.tools) {
            const prevMicroflows = prevMicroflowsRef.current;
            const currentMicroflows = new Map<string, string>();

            // First, build the current microflows map
            agent.tools.forEach((tool) => {
                if (tool.microflow) {
                    currentMicroflows.set(tool.id, tool.microflow);
                }
            });

            // Then update validation state
            setToolValidations((prev) => {
                const updated = new Map(prev);

                agent.tools?.forEach((tool) => {
                    if (!prev.has(tool.id)) {
                        // New tool - set to valid
                        updated.set(tool.id, "valid");
                    } else {
                        // Check if tool was edited (microflow changed)
                        const prevMicroflow = prevMicroflows.get(tool.id);
                        const currentMicroflow = currentMicroflows.get(tool.id);
                        if (
                            prevMicroflow !== undefined &&
                            currentMicroflow !== undefined &&
                            prevMicroflow !== currentMicroflow
                        ) {
                            // Tool was edited - set to valid
                            updated.set(tool.id, "valid");
                        }
                    }
                });

                return updated;
            });

            // Finally, update the ref for next time
            prevMicroflowsRef.current = currentMicroflows;
        }
    }, [agent.tools, isLoaded]);

    useEffect(() => {
        const triggerValiation = async () => {
            const validationInfo = await validateAgent(agent);
            setValidationInfo(validationInfo);
        };

        if (isLoaded) {
            triggerValiation();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [studioPro, agent]);

    const highlightRules = useMemo(() => createHighlightRules(agent.variables), [agent.variables]);

    // Debounced handlers for text fields
    const onTextAreaChange = (field: keyof Agent) => (value: string) => {
        const agentWithUpdatedField: Agent = { ...agent, [field]: value };
        setAgent(agentWithUpdatedField);
        if (debounceTimeout.current) {
            clearTimeout(debounceTimeout.current);
        }
        debounceTimeout.current = setTimeout(async () => {
            const updatedAgent = await handleAgentChangeValue(
                studioPro,
                theme,
                field,
                agentWithUpdatedField,
                updateStudioProDocument,
                value
            );
            setAgent(updatedAgent);
        }, 300);
    };

    //Handlers for selection buttons
    const selectEntity = async () => {
        const updatedAgent = await handleSelectEntity(studioPro, agent, updateStudioProDocument);
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    };

    const selectModel = async () => {
        const updatedAgent = await handleSelectModel(studioPro, agent, updateStudioProDocument);
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    };

    const showModel = async () => {
        if (agent.modelQualifiedName) {
            handleShowModel(studioPro, agent.modelQualifiedName);
        }
    };

    const showEntity = async () => {
        handleShowEntity(studioPro, agent.entity);
    };

    const editModelSettings = async () => {
        const updatedAgent = await handleEditModelSettings(studioPro, componentName, agent, updateStudioProDocument);
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    };

    //Page-specific UI functions
    const getEntityIcon = async (
        studioPro: StudioProApi,
        entityName?: string
    ): Promise<React.ReactElement | undefined> => {
        if (!entityName) {
            return undefined;
        }
        const entity = await getEntity(studioPro, entityName);
        if (!entity) {
            return undefined;
        }
        const isPersistable = await isPersistableEntity(entity, studioPro);
        if (isPersistable === undefined) {
            return undefined;
        }
        return isPersistable ? <EntityIcon /> : <EntityNonPersistableIcon />;
    };

    const modelSettings = useMemo(() => {
        let modelSettingsString = "";
        if (agent.maxTokens !== undefined) {
            modelSettingsString += "Max tokens: " + agent.maxTokens.toLocaleString(navigator.language);
        }
        if (agent.temperature !== undefined) {
            if (modelSettingsString.length > 0) {
                modelSettingsString += ", ";
            }
            modelSettingsString +=
                "Temperature: " +
                agent.temperature.toLocaleString(navigator.language, {
                    minimumFractionDigits: 1,
                    maximumFractionDigits: 2,
                });
        }
        if (agent.topP !== undefined) {
            if (modelSettingsString.length > 0) {
                modelSettingsString += ", ";
            }
            modelSettingsString +=
                "Top P: " +
                agent.topP.toLocaleString(navigator.language, { minimumFractionDigits: 1, maximumFractionDigits: 2 });
        }
        return modelSettingsString;
    }, [agent.temperature, agent.maxTokens, agent.topP]);

    const validateAgent = async (agent: Agent): Promise<ValidationInfo> => {
        return {
            isValidModel: await handleValidateAgent("modelQualifiedName", studioPro, agent),
            isValidEntity: await handleValidateAgent("entity", studioPro, agent),
            isValidUserPrompt: await handleValidateAgent("userPrompt", studioPro, agent),
            showCreateVariablesInfo: agent.variables.length === 0,
            missingAttributes: await getMissingAttributes(studioPro, agent),
            unusedAttributes: await getUnusedAttributes(studioPro, agent),
        };
    };

    return (
        <>
            <ContentColumn>
                <GroupBox label="System prompt">
                    <TextAreaLabeled
                        ariaLabel="System prompt"
                        value={agent.systemPrompt}
                        onChange={onTextAreaChange("systemPrompt")}
                        highlightRules={highlightRules}
                    />
                </GroupBox>
                <GroupBox label="User prompt">
                    <TextAreaLabeled
                        ariaLabel="User prompt"
                        value={agent.userPrompt || ""}
                        onChange={onTextAreaChange("userPrompt")}
                        highlightRules={highlightRules}
                        validate={() => validationInfo.isValidUserPrompt}
                    />
                </GroupBox>
                <ToolsTable
                    agent={agent}
                    studioPro={studioPro}
                    componentName={componentName}
                    updateStudioProDocument={updateStudioProDocument}
                    onAgentChange={setAgent}
                    toolValidations={toolValidations}
                />
            </ContentColumn>
            <ContentColumn>
                <GroupBox label="General">
                    <TextInputWithButton
                        ariaLabel="Model"
                        label="Model"
                        value={agent.modelQualifiedName ? agent.modelQualifiedName : ""}
                        icon={agent.modelQualifiedName ? mendixCloudGenAIIconBase64 : undefined}
                        buttonCaption="Select..."
                        onClick={selectModel}
                        validate={() => validationInfo.isValidModel}
                        buttonCaptionSecondary={agent.modelQualifiedName ? "Show" : undefined}
                        onClickSecondary={agent.modelQualifiedName ? showModel : undefined}
                    />
                    <TextInputWithButton
                        ariaLabel="Settings"
                        label="Model settings"
                        value={modelSettings}
                        buttonCaption="Edit"
                        onClick={editModelSettings}
                        validate={undefined}
                    />
                    <TextArea
                        label="Documentation"
                        aria-label="Documentation"
                        value={agent.description}
                        onChange={onTextAreaChange("description")}
                        rows={3}
                    />
                    <TextInputWithButton
                        ariaLabel="Entity"
                        label="Entity"
                        value={agent.entity}
                        icon={entityIcon}
                        onClick={selectEntity}
                        buttonCaption="Select..."
                        validate={() => validationInfo.isValidEntity}
                        buttonCaptionSecondary={agent.entity ? "Show" : undefined}
                        onClickSecondary={agent.entity ? showEntity : undefined}
                    />
                    {validationInfo.showCreateVariablesInfo &&
                        validationInfo.unusedAttributes.length === 0 &&
                        !hideNoVariables && (
                            <InfoBanner onClose={() => setHideNoVariables(true)}>
                                {`Create variables: Enclose a word or text in double curly brackets. For example, you can write {{Language}} in the system or user prompt.`}
                            </InfoBanner>
                        )}
                    {validationInfo.missingAttributes.length > 0 && (
                        <WarningBanner>
                            <span>{`The following attributes cannot be found on the selected entity:`}</span>
                            <ul>
                                {validationInfo.missingAttributes.map((a) => (
                                    <li key={a}>{a}</li>
                                ))}
                            </ul>
                        </WarningBanner>
                    )}
                    {validationInfo.unusedAttributes.length > 0 && !hideUnusedAttributes && (
                        <InfoBanner onClose={() => setHideUnusedAttributes(true)}>
                            {validationInfo.showCreateVariablesInfo && (
                                <>
                                    <span>{`Create variables: Enclose a word or text in double curly brackets. For example, you can write {{Language}} in the system or user prompt.`}</span>
                                    <br></br>
                                </>
                            )}
                            <span>{`The following attributes are found on the selected entity, but are not used in the prompt:`}</span>
                            <ul>
                                {validationInfo.unusedAttributes.map((a) => (
                                    <li key={a}>{a}</li>
                                ))}
                            </ul>
                        </InfoBanner>
                    )}
                </GroupBox>
            </ContentColumn>
        </>
    );
};

export default AgentEditor;
