import { DocumentsOfTypeResult, SelectorResult, StudioProApi } from "@mendix/extensions-api";
import { Agent } from "../../types/agent";
import { calculateVariables, checkAttributes, isAgentEntityFound } from "../../utils/agentUtils";
import { modelDocumentTypeId } from "../../main";
import { Tool } from "../../types/tool";
import { DefaultTheme } from "styled-components";

export const handleAgentChangeValue = async (
    studioPro: StudioProApi,
    theme: DefaultTheme,
    field: keyof Agent,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>,
    value: string
): Promise<Agent> => {
    const updatedAgent = { ...agent, [field]: value };
    if (field === "userPrompt" || field === "systemPrompt") {
        updatedAgent.variables = await calculateVariables(studioPro, theme, updatedAgent);
    }
    updateAgentDocument(updatedAgent);
    return updatedAgent;
};

export const handleSelectEntity = async (
    studioPro: StudioProApi,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>
): Promise<Agent | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectEntity({ allowNone: true });
    let updatedAgent: Agent | undefined = undefined;
    if (selectorResult.status === "ok") {
        updatedAgent = { ...agent, entity: selectorResult.selected.module + "." + selectorResult.selected.name };
    }
    if (selectorResult.status === "none") {
        updatedAgent = { ...agent, entity: "" };
    }
    if (updatedAgent) {
        const recalculatedVariables = await checkAttributes(studioPro, agent.variables, updatedAgent);
        updatedAgent = { ...updatedAgent, variables: recalculatedVariables };
        updateAgentDocument(updatedAgent);
    }
    return updatedAgent;
};

export const handleSelectModel = async (
    studioPro: StudioProApi,
    agent: Agent,
    updateAgentDocument: (agent: Agent) => Promise<void>
): Promise<Agent | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        allowNone: true,
        query: { elementType: modelDocumentTypeId },
    });
    let updatedAgent: Agent | undefined = undefined;
    if (selectorResult.status === "ok") {
        updatedAgent = {
            ...agent,
            modelQualifiedName: selectorResult.selected.module + "." + selectorResult.selected.name,
        };
    }
    if (selectorResult.status === "none") {
        updatedAgent = { ...agent, modelQualifiedName: undefined };
    }
    if (updatedAgent) {
        updateAgentDocument(updatedAgent);
    }
    return updatedAgent;
};

